node - <<'E' const fs=require('fs'); function sub(p,a,b){let s=fs.readFileSync(p,'utf8'); if(!s.includes(a)) throw new Error(p+': '+a.slice(0,40)); fs.writeFileSync(p,s.replace(a,()=>b));} let p='src/subscriptions/proration.mjs'; sub(p,`/**  * The share of a period left at a change date, as whole days. The change day  * itself was already paid for under the old plan, so the time left starts on the  * following day.  */`,`/**  * The share of a period left at a change date, as whole days. The new terms  * apply from the morning of the change date, so that day counts as time left.  */`); sub(p,"remaining: daysBetween(addDays(changeDate, 1), period.end),","remaining: daysBetween(changeDate, period.end),"); sub(p,"import { addDays, compareDates, daysBetween }","import { compareDates, daysBetween }"); p='src/subscriptions/segments.mjs'; sub(p,"import { seatCharge } from '../catalog/plans.mjs';
import { prorateAmount } from './proration.mjs';","import { compareDates, daysBetween } from '../core/dates.mjs';
import { scaleRounded } from '../core/rounding.mjs';"); let s=fs.readFileSync(p,'utf8'); s=s.slice(0,s.indexOf('/**
 * The credit for the rest'))+`/**  * The credit for the rest of the current segment at \`date\`: the share of what  * the segment was charged, after discount, that is still to run. Never more than  * what is left of that charge once earlier credits are taken off.  *  * @param {object} record the subscription  * @param {string} date the day the old terms stop  * @param {number} reversedNet what has already gone back on the segment's line  */ export function unusedCredit(record, date, reversedNet = 0) {   const { segment } = record;   if (compareDates(date, segment.from) < 0 || compareDates(date, segment.to) >= 0) {     throw new RangeError(\`\${date} is outside the current terms, \${segment.from} to \${segment.to}\`);   }   const unused = scaleRounded(segment.net, daysBetween(date, segment.to), daysBetween(segment.from, segment.to));   return Math.max(Math.min(unused, segment.net - reversedNet), 0); } `; fs.writeFileSync(p,s); p='src/subscriptions/plan-change.mjs'; sub(p,"      taxRateBps,
      period: servicePeriod,
      reverses: reversalLink(record.segment),","      taxRateBps: record.segment.taxRateBps,
      period: servicePeriod,
      reverses: reversalLink(record.segment),"); sub(p,"discount: discountFor(record, period.index),","discount: discountFor(record, period.index, { midPeriod: true }),"); sub(p,"    couponUses: nextCouponUses(record),
    plan,","    plan,"); sub(p,"import { discountFor, nextCouponUses } from","import { discountFor } from"); sub(p,"        taxRateBps,
        period: { start: date, end: record.period.end },","        taxRateBps: record.segment.taxRateBps,
        period: { start: date, end: record.period.end },"); sub(p,"  const { number, taxRateBps, reversedNet } = context;
  const credit = unusedCredit","  const { number, reversedNet } = context;
  const credit = unusedCredit"); p='src/subscriptions/renewal.mjs'; sub(p,`/** The invoice discount for charges in a billing period, or null. */ export function discountFor(record, periodIndex) {   const coupon = couponFor(record, periodIndex);`,`/**  * The invoice discount for charges in a billing period, or null. Uses are counted  * when a period is invoiced, so the period in progress has already used one: a  * mid-period change is covered while the coupon has not run past its periods.  */ export function discountFor(record, periodIndex, { midPeriod = false } = {}) {   const inProgress =     record.coupon && (record.coupon.periods === null || record.couponUses <= record.coupon.periods);   const coupon = midPeriod ? (inProgress ? record.coupon : null) : couponFor(record, periodIndex);`); E sed -n 25,50p src/subscriptions/plan-change.mjs
